  }

  input[type="checkbox"] {
    border: 1px solid ButtonBorder;
  }

  input[type="checkbox"]:focus-visible {
    outline: 2px solid Highlight;
  }

  .submit-button {
    border: 1px solid ButtonBorder;
  }
}

/* Responsive design */
@media (max-width: 600px) {
  main {
    padding: 16px;
  }

  .form-container {
    padding: 24px;
  }

  h1 {
    font-size: 20px;
    margin-bottom: 24px;
  }

  label {
    font-size: 14px;
  }

  .submit-button {
    padding: 14px 20px;
    font-size: 16px;
  }
}
