', direction=None, fact=None, file_name='/workspace/sandbox/skills/building-accessible-ui/single-checkbox--framework-react--style-dark/claude-haiku-4.5__s2/test-functionality.js', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents='const { chromium } = require('playwright');
const { AxeBuilder } = require('@axe-core/playwright');
const path = require('path');

async function runAllTests() {
  const browser = await chromium.launch();
  const context = await browser.newContext();
  const page = await context.newPage();

  const filePath = path.resolve(__dirname, 'index.html');
  await page.goto(`file://${filePath}`);

  console.log('=== Accessibility Test ===');
  const results = await new AxeBuilder({ page }).analyze();

  if (results.violations.length === 0) {
    console.log('✓ No accessibility violations');
  } else {
    console.log(`✗ Found ${results.violations.length} violation(s)`);
    results.violations.forEach((violation) => {
      console.log(`  - ${violation.id}: ${violation.description}`);
    });
  }

  console.log('\n=== Functional Tests ===');

  // Test 1: Checkbox exists and is required
  const checkbox = await page.$('#consent-checkbox');
  if (checkbox) {
    const required = await checkbox.evaluate(el => el.required);
    console.log(required ? '✓ Checkbox is required' : '✗ Checkbox is not required');
  } else {
    console.log('✗ Checkbox not found');
  }

  // Test 2: Label exists and is associated
  const label = await page.$('label[for="consent-checkbox"]');
  if (label) {
    console.log('✓ Label properly associated with checkbox');
  } else {
    console.log('✗ Label not found');
  }

  // Test 3: Helper text exists
  const helper = await page.$('#consent-help');
  if (helper) {
    console.log('✓ Helper text present');
  } else {
    console.log('✗ Helper text missing');
  }

  // Test 4: Error text element exists
  const error = await page.$('#consent-error');
  if (error) {
    console.log('✓ Error text element present');
  } else {
    console.log('✗ Error text missing');
  }

  // Test 5: Form field wrapper exists
  const formField = await page.$('.form-field');
  if (formField) {
    console.log('✓ Form field wrapper present');
  } else {
    console.log('✗ Form field wrapper missing');
  }

  // Test 6: Submit button exists
  const button = await page.$('button[type="submit"]');
  if (button) {
    const text = await button.textContent();
    console.log(text ? '✓ Submit button present with text' : '✗ Submit button missing text');
  } else {
    console.log('✗ Submit button not found');
  }

  // Test 7: Form submission validation
  const submitButton = await page.$('button[type="submit"]');
  if (submitButton) {
    await submitButton.click();

    // Check if error message is shown
    await page.waitForTimeout(100);
    const errorVisible = await page.$('#consent-error:not([hidden])');
    if (errorVisible) {
      console.log('✓ Error message displayed when checkbox unchecked');
    } else {
      console.log('✗ Error message not displayed');
    }
  }

  // Test 8: Check dark theme
  const bgColor = await page.evaluate(() => {
    return getComputedStyle(document.querySelector('.form-container')).backgroundColor;
  });
  console.log(`✓ Container background applied: ${bgColor}`);

  // Test 9: Checkbox acceptance workflow
  await page.click('#consent-checkbox');
  await page.waitForTimeout(100);
  const errorHiddenAfterCheck = await page.$('#consent-error[hidden]');
  if (errorHiddenAfterCheck) {
    console.log('✓ Error clears when checkbox is checked');
  } else {
    console.log('✗ Error did not clear');
  }

  await browser.close();
  console.log('\n=== All tests completed ===');
}

