  justify-content: center;
  padding: 20px;
}

.form-container {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 40px;
  max-width: 500px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

h1 {
  margin: 0 0 30px;
  font-size: 24px;
  font-weight: 600;
  color: var(--text-primary);
}

h2 {
  margin: 0 0 16px;
  font-size: 16px;
  font-weight: 600;
  color: var(--text-primary);
}

form {
  display: flex;
  flex-direction: column;
  gap: 24px;
  margin-bottom: 32px;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

label {
  display: block;
  font-size: 15px;
  font-weight: 500;
  color: var(--text-primary);
  cursor: pointer;
  user-select: none;
}

label span[aria-hidden="true"] {
  color: var(--error-color);
  margin-left: 4px;
}

label a {
  color: #64b5f6;
  text-decoration: underline;
  border-bottom: 1px solid transparent;
  transition: all 0.2s;
}

label a:hover {
  color: #90caf9;
}

label a:focus {
  outline: 2px solid var(--focus-color);
  outline-offset: 2px;
  border-radius: 2px;
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin-right: 12px;
  cursor: pointer;
  accent-color: var(--accent-color);
  vertical-align: middle;
}

input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--focus-color);
  outline-offset: 2px;
  border-radius: 4px;
}

input[type="checkbox"][aria-invalid="true"] {
  border: 2px solid var(--error-color);
  outline: 2px solid var(--error-color);
  outline-offset: 2px;
}

.form-help {
  margin: 0;
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.4;
}

.form-error {
  margin: 0;
  font-size: 13px;
  color: var(--error-color);
  line-height: 1.4;
}

.submit-button {
  padding: 12px 24px;
  background-color: #3a6fa8;
  color: white;
  border: none;
  border-radius: 6px;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s, box-shadow 0.2s;
}

.submit-button:hover:not(:disabled) {
  background-color: #2f5c8f;
  box-shadow: 0 4px 12px rgba(58, 111, 168, 0.3);
}

.submit-button:focus-visible {
  outline: 2px solid var(--focus-color);
  outline-offset: 2px;
}

.submit-button:active:not(:disabled) {
  transform: scale(0.98);
}

.submit-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.terms-summary {
  padding: 20px;
  background-color: var(--bg-tertiary);
  border: 1px solid var(--border-color);
  border-radius: 8px;
}

.terms-summary p {
  margin: 0;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* Focus visible for all interactive elements */
button:focus-visible,
a:focus-visible {
  outline: 2px solid var(--focus-color);
  outline-offset: 2px;
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* High contrast / forced colors support */
@media (forced-colors: active) {
  .form-container {
    border: 2px solid CanvasText;
    background-color: Canvas;
  }

  input[type="checkbox"] {
    border: 1px solid ButtonBorder;
  }

  input[type="checkbox"]:focus-visible {
    outline: 2px solid Highlight;
  }

  .submit-button {
    border: 1px solid ButtonBorder;
  }
}

/* Responsive design */
@media (max-width: 600px) {
  main {
    padding: 16px;
  }

  .form-container {
    padding: 24px;
  }

  h1 {
    font-size: 20px;
    margin-bottom: 24px;
  }

  label {
    font-size: 14px;
  }

  .submit-button {
    padding: 14px 20px;
    font-size: 16px;
  }
}
